selection_review=[
 {'pages':[3,4,16],'wording':'any four / any two questions','classification':'exam-level-selection','reason':'Retain all ten questions and 380 offered marks despite 220 candidate marks.'},
 {'pages':[5],'wording':'Write each number','classification':'required-answers','reason':'All six number placements are required; one 10D allocation.'},
 {'pages':[6],'wording':'any odd number','classification':'universal-proof','reason':'Universal proposition and induction proof, not a finite choice.'},
 {'pages':[14],'wording':'each of the following points','classification':'required-headings','reason':'All three points required together under one 20D allocation.'},
 {'pages':[22],'wording':'all three roots','classification':'required-answers','reason':'All polynomial roots required; no choice.'},
 {'pages':[24],'wording':'infinite number of different possible quadratic functions','classification':'open-answer','reason':'One valid quadratic model, not a fixed pool or separate cards for alternative models.'},
]
def classify(c):
 t=c['context'].lower()
 if 'questions' in t and 'any' in t:return ('exam-level-selection','All ten offered questions retained.')
 if 'odd number' in t:return ('universal-proof','Any means every odd number in this proposition, not a finite selection.')
 return None
if __name__=='__main__':p.write(selection_review,classify)
